#ifndef __ARM_2D_SCENE_BLINK_H__
#define __ARM_2D_SCENE_BLINK_H__

/*============================ INCLUDES ======================================*/

#if defined(_RTE_)
#   include "RTE_Components.h"
#endif

#if defined(RTE_Acceleration_Arm_2D_Helper_PFB)

