#   define __ARM_2D_IMPL__
#endif
#ifdef __USER_SCENE_BLINK_INHERIT__
#   define __ARM_2D_INHERIT__
#endif
#include "arm_2d_utils.h"

#ifndef ARM_2D_DEMO_BLINK_USE_QOI
